"""Source-specific display language; no new physical specimen associations."""
SPECS={}
def add(sid,title,headline,caption,facts,phase=None):
 SPECS[sid]={'title':title,'headline':headline,'caption':caption,'facts':['sasongko2025-'+f for f in facts],'phase':phase}
add('fa-stock','Prepared FA precursor','Operational FA-oleate stock','The source names the prepared solution FA-oleate. Its final concentration, dissolved coordination and storage are unreported. The complete preparation and later injection aliquot remain separate.',['fa-charge','fa-vacuum','fa-hot'])
for n in [2,3,4]:
 add(f'ligand-1-{n}',f'Ligand comparison — OAm:OA 1:{n}',f'OAm:OA 1:{n} by volume',f'Figure 1 compares this condition at 100 °C with acetonitrile:toluene 1:20 washing. Diffraction widths and optical lifetimes are source comparison results; no exact cross-technique aliquot, phase fraction or ligand occupancy is established.',['ligand-design','ligand-xrd','ligand-optical'],'Source FAPbI3 diffraction assignment; phase fractions unquantified')
for n in [1,10,20]:
 add(f'wash-1-{n}',f'Washing comparison — 1:{n}',f'Acetonitrile:toluene 1:{n}',f'Figure 2 compares this washing ratio by volume at fixed 100 °C growth and OAm:OA 1:3. It is one paired purification condition, not another independent full experimental matrix. Absolute washing amounts and whole-product composition are unknown.',['wash-design','wash-results'])
for t in [25,50,100]:
 phase='α-FAPbI3 + δ-FAPbI3 + PbI2 source assignments' if t==25 else 'α-FAPbI3 source assignment; no quantitative phase fraction'
 cap=f'Figure 3 compares {t} °C growth at OAm:OA 1:3 and acetonitrile:toluene 1:20. TEM dimensions, histogram width and optical lifetime retain their separate measurement meanings. The reported ± statistic is undefined. Phase assignments do not establish a pure whole batch or an exact shared aliquot.'
 if t==100:cap+=' The inset prints d(002) = 6.38 Å; the conflict with the quoted 6.36 Å cubic cell remains unresolved.'
 add(f'growth-{t}',f'Growth comparison — {t} °C',f'{t} °C synthesis condition',cap,['temperature-design','temperature-phase','temperature-size','temperature-lifetimes']+(['fringe'] if t==100 else []),phase)
add('crude','Post-injection crude dispersion','Promptly cooled reaction mixture','This is the crude dispersion after FA-stock injection and prompt cooling. Growth dwell and numerical room temperature are unreported. No purified-product composition or atomic model is assigned.',['qd-inject'])
add('first-precipitate','Retained first precipitate','Retained fraction after first centrifugation','The first centrifugation retains the precipitate for redispersion. It is distinct from the discarded washing fraction and from the later stored supernatant. Its whole composition is unreported.',['wash-formulation','wash-spin'])
add('washing-waste','Washing-waste observation','Original Figure S1 waste vials','Figure S1 compares waste associated with OAm:OA 1:2, 1:3 and 1:4. The caption associates 1:4 with partial QD dissolution. This is a discarded-fraction observation, not the retained final product or a dissolved-mass measurement.',['washing-photo'])
add('hexane-redispersion','Hexane redispersion','Retained precipitate redispersed in hexane','The source redisperses the first precipitate in hexane before clarification. Hexane volume, final concentration and exact isomer are not reported. No solution or particle geometry is inferred.',['redisperse'])
add('final-supernatant','Stored final supernatant','Retained product fraction after clarification','The second centrifugation retains the supernatant for characterization. Storage conditions and concentration are unreported. This fraction does not acquire a precise physical-batch join to every later optical or diffraction result.',['clarify-spin'])
add('temperature-pl','Variable-temperature PL','80–430 K optical measurement','Figures 4 and 5 track PL energy, width and intensity during measurement-temperature variation. Changes at 140 and 250 K support the authors’ γ→β→α interpretation. Enhancement through 350 K and decline above it are optical regimes, not additional synthesis conditions or atomic refinements.',['pl-temperature-scan','pl-gamma','pl-beta','pl-alpha','pl-overheat'])
add('temperature-raman','Variable-temperature Raman','Figure S2: displayed 80–190 K','The prose gives an attempted 80–200 K range, but PL overlap limits useful data above 190 K; Figure S2 displays 80–190 K. The misplaced Figure S1 callout is preserved as a source conflict. Cited PbO2 or other phase-mode explanations do not establish current contaminants.',['raman-range','raman-observation','raman-reference'])
add('aging-350','Thermal-aging PL observation','350 K aging series','Figure S3 compares a 300 K spectrum with spectra during 350 K aging. The normalized PL-intensity fit describes a slight decline; it is not absolute quantum yield or evidence of a new phase. Aging time is not a synthesis dwell.',['thermal-stability'])
for name,group in [('gamma','γ tetragonal P4/mbm'),('beta','β tetragonal P4/mbm'),('alpha','α cubic Pm3m')]:
 add(name+'-reference',f'Quoted {name} reference cell',group+' — quoted reference',('The paper quotes external reference-cell parameters for its conceptual phase discussion. They are not a refinement of the current QDs. '+('The literal printed Pm3m is retained without inserting an overbar. ' if name=='alpha' else '')+'No atomic positions, occupancies or CIF are supplied.'),['cited-cell-'+name])
add('phase-model','Phase and emission interpretation','Source Scheme 1 conceptual interpretation','Scheme 1 relates the authors’ γ→β→α interpretation to optical regimes and proposed trap, strain and excitonic mechanisms. Atomic-looking source icons are explanatory drawings, not recoverable current-sample coordinates. No atomic reconstruction is proposed.',['scheme-model'])
